def _normaliza(nome):
    """Cópia fixa da regra de website/autores.py: uma migration não pode depender de código que continua mudando."""
    sem_acento = unicodedata.normalize('NFKD', (nome or '').replace('{', '').replace('}', '').strip())
    sem_acento = ''.join(c for c in sem_acento if not unicodedata.combining(c))
    return re.sub(r'\s+', ' ', sem_acento).casefold()


def textos_para_autores(apps, schema_editor):
    """O texto "Ana Silva, João Souza" vira uma linha por autor; o nome que bate com um membro fica vinculado."""
    Article = apps.get_model('website', 'Article')
    ArticleAuthor = apps.get_model('website', 'ArticleAuthor')
    Member = apps.get_model('website', 'Member')
    por_nome = {}
    for membro in Member.objects.all():
        por_nome.setdefault(_normaliza(membro.name), []).append(membro)
    for artigo in Article.objects.exclude(authors=''):
        nomes = [n.strip() for n in artigo.authors.split(',') if n.strip()]
        for ordem, nome in enumerate(nomes):
            candidatos = por_nome.get(_normaliza(nome), [])
            membro = candidatos[0] if len(candidatos) == 1 else None
            if membro is None:
                print(f'\n  artigo "{artigo.title}": autor sem membro vinculado: {nome}')
            ArticleAuthor.objects.create(article=artigo, member=membro, name=nome, order=ordem)


def autores_para_textos(apps, schema_editor):
    """Desfaz: remonta o texto dos autores, na ordem, sem as chaves do BibTeX."""
    Article = apps.get_model('website', 'Article')
    ArticleAuthor = apps.get_model('website', 'ArticleAuthor')
    for artigo in Article.objects.all():
        nomes = [a.name.replace('{', '').replace('}', '') for a in ArticleAuthor.objects.filter(article=artigo).order_by('order')]
        if artigo.institutional and not nomes:
            nomes = ['Insper Consulting Club']
        if nomes:
            Article.objects.filter(pk=artigo.pk).update(authors=', '.join(nomes)[:300])


